-- V1.0.60__seed_writing_topics.sql
-- 目标库：exercise_db
-- 依据：D:/AI-EnglishLearning/英语资源/格式化数据 下 66 份整卷真题 JSON（CET4 32 / CET6 34），
--       每份取 sections.writing[0] 的 prompt 与 requiredWords，来源可追溯至真题 PDF。
-- 与前端 mocks/writing.ts 的 10 道演示题无关，那批数据不入库（isPreview 标记即其性质）。
-- 字段映射：topic_key=examId / level=level / topic=清洗后的英文 prompt / directions=中文指令 /
--          type 按五档判定（CHART_ESSAY > REPORT > LETTER > QUOTE_ESSAY > ESSAY，见下方说明）/
--          word_range_min=requiredWords / word_range_max=prompt 内 "no(t) more than N words" /
--          time_limit_seconds=1800（题干均写明 30 minutes）/ source=CET4 2022年6月 第1套。
-- 题型枚举扩为五档（原前端只有 SHORT_ESSAY/PRACTICAL 两档，装不下真题实际题型）：
--   CHART_ESSAY 图表作文（须配图，本次 3 条因缺图 OFFLINE）
--   REPORT      报道（write a report to ...）
--   LETTER      书信体（proposal / letter / application / email / notice 等）
--   QUOTE_ESSAY 引语作文（题干给定首句，须抄写在开头）
--   ESSAY       命题议论文（其余）
-- ⚠ 前端 frontend/src/types/writing.ts 的 type 联合类型须同步扩为这五档，否则 type-check 不通过。
-- 真题不含 title / requirements / outline_hints / useful_expressions，后三项一律 NULL，不编造。
-- 清洗：修 PDF 拆词（o f / t o / f or / sen tence）、缺空格（逗号句号后）、重复句。
-- 例外：3 道图表作文（cet6-2021-06 三套）题干要求"根据下图/下表写作"，但源 JSON 无任何图表数据，
--       且 writing_topic 无图片字段，故 status=OFFLINE 下架入库（数据不丢、考生看不到废题），
--       待补齐图表并新增图片字段后再 UPDATE 为 PUBLISHED。
-- 风险等级：低（纯 INSERT，无 DDL）；回滚方式：DELETE FROM `writing_topic` WHERE `source` IS NOT NULL;

INSERT INTO `writing_topic`
  (`topic_key`, `type`, `level`, `title`, `directions`, `topic`,
   `word_range_min`, `word_range_max`, `time_limit_seconds`, `source`, `sort_order`, `status`)
VALUES
  ('cet4-2022-06-1', 'LETTER', 'CET4', '建议信：改善图书馆服务', '就图书馆服务的现存问题提出改进建议，写一封不少于 120 词的建议信。', 'Suppose you are going to write a proposal to your school library for improving its service. You are to write about its current problems and possible solutions to these problems. You will have 30 minutes to write the proposal. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2022年6月 第1套', 1, 'PUBLISHED'),
  ('cet4-2022-06-2', 'LETTER', 'CET4', '建议信：丰富课外活动', '向学生会建议组织哪些课外活动并说明理由，不少于 120 词。', 'Suppose you are going to write a proposal to your student union for enriching students’ extracurricular activities. You are to write about what activities to organize and why. You will have 30 minutes to write the proposal. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2022年6月 第2套', 2, 'PUBLISHED'),
  ('cet4-2022-06-3', 'LETTER', 'CET4', '建议信：改善校医务室', '就校医务室服务的现存问题提出改进建议，不少于 120 词。', 'Suppose you are going to write a proposal to your school clinic for improving its service. You are to write about its current problems and possible solutions to these problems. You will have 30 minutes to write the proposal. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2022年6月 第3套', 3, 'PUBLISHED'),
  ('cet4-2022-09-1', 'LETTER', 'CET4', '申请信：暑期支教', '申请参加暑期支教活动，说明申请理由与你能为孩子们做的事，不少于 120 词。', 'Suppose your university is selecting some students to teach kids in remote rural areas during the coming vacation. You are now to write an application letter to the university to explain why you want to take part and what you can do for the kids. You will have 30 minutes to write the letter. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2022年9月 第1套', 4, 'PUBLISHED'),
  ('cet4-2022-09-2', 'REPORT', 'CET4', '报道：教师节庆祝活动', '为校报撰写班级教师节庆祝活动的报道，不少于 120 词。', 'Suppose your class has just finished celebrating the Teachers''Day. You are now to write a report to the university newspaper on the celebration activities organized by your class. You will have 30 minutes to write the report. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2022年9月 第2套', 5, 'PUBLISHED'),
  ('cet4-2022-12-1', 'ESSAY', 'CET4', '体育锻炼与学业成功', '论述体育锻炼对在大学取得学业成功的作用，不少于 120 词。', 'In this task, you are to write an essay on the role of physical exercise in achieving success at college. You will have 30 minutes for the task. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2022年12月 第1套', 6, 'PUBLISHED'),
  ('cet4-2022-12-2', 'ESSAY', 'CET4', '健康生活方式的重要性', '论述大学生养成健康生活方式的重要性，不少于 120 词。', 'In this task, you are to write an essay on the importance of developing a healthy lifestyle among college students. You will have 30 minutes for the task. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2022年12月 第2套', 7, 'PUBLISHED'),
  ('cet4-2022-12-3', 'ESSAY', 'CET4', '培养社交能力的必要性', '论述大学生培养社交能力的必要性，不少于 120 词。', 'In this task, you are to write an essay on the necessity of developing social skills for college students. You will have 30 minutes for the task. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2022年12月 第3套', 8, 'PUBLISHED'),
  ('cet4-2023-03-1', 'ESSAY', 'CET4', '记述职业规划讲座', '记述你参加的职业规划讲座，并总结从中获得的收获，不少于 120 词。', 'Suppose you have taken part in a career planning seminar. Write an account of the seminar and summarize what you have learned from it. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2023年3月 第1套', 9, 'PUBLISHED'),
  ('cet4-2023-03-2', 'ESSAY', 'CET4', '向读书会推荐一本书', '在读书会在线论坛介绍一本你读过的书，说明它值得一读的理由，不少于 120 词。', 'Suppose you have read a book recently and intend to recommend it to other members of your book club via an online forum. Briefly introduce the book and explain why it is worth reading. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2023年3月 第2套', 10, 'PUBLISHED'),
  ('cet4-2023-03-3', 'REPORT', 'CET4', '报道：名学者讲座', '为校报撰写名学者讲座报道，概括其最重要的观点，不少于 120 词。', 'Suppose you have attended a lecture delivered by a famous scholar. Write a report to the campus newspaper, summarizing its most important points. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2023年3月 第3套', 11, 'PUBLISHED'),
  ('cet4-2023-06-1', 'QUOTE_ESSAY', 'CET4', '心理健康与身体健康', '以给定句子开头，论述心理健康应得到与身体健康同等的重视，不少于 120 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence " Today there is a growing awareness that mental well-being needs to be given as much attention as physical health." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2023年6月 第1套', 12, 'PUBLISHED'),
  ('cet4-2023-06-2', 'ESSAY', 'CET4', '如何维系同学友谊', '论述与同学保持温暖友好关系的方法，以及这种关系带来的益处，不少于 120 词。', 'Suppose the student union of your university is organizing an online discussion on interpersonal relationships. You are to write an essay on ways to maintain a warm and friendly relationship with your classmates and on the benefits of such a relationship. You will have 30 minutes for the task. You should write at least 120 words but no more than 180 words .', 120, 180, 1800, 'CET4 2023年6月 第2套', 13, 'PUBLISHED'),
  ('cet4-2023-06-3', 'ESSAY', 'CET4', '大学生社区服务的益处', '论述大学生参与社区服务的益处，以及你能为社区提供哪些服务，不少于 120 词。', 'Suppose the student union of your university is organizing an online discussion on college students doing community service. You are to write an essay on its benefits and the service you can provide to the community. You will have 30 minutes for the task. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2023年6月 第3套', 14, 'PUBLISHED'),
  ('cet4-2023-12-1', 'ESSAY', 'CET4', '投稿：最难忘的校园活动', '为校报投稿，写一件最打动你的校园活动，不少于 120 词。', 'Suppose the university newspaper is inviting submissions from the students for its coming edition on a campus event that has impressed them most. You are now to write an essay for submission. You will have 30 minutes to write the essay. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2023年12月 第1套', 15, 'PUBLISHED'),
  ('cet4-2023-12-2', 'ESSAY', 'CET4', '投稿：家乡的新变化', '为校报投稿，写家乡近年来的发展变化，不少于 120 词。', 'Suppose the university newspaper is inviting submissions from the students for its coming edition on the recent development in their hometown. You are now to write an essay for submission. You will have 30 minutes to write the essay. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2023年12月 第2套', 16, 'PUBLISHED'),
  ('cet4-2023-12-3', 'ESSAY', 'CET4', '投稿：校园最打动我之处', '为校报投稿，写学校里最让你印象深刻的地方，不少于 120 词。', 'Suppose the university newspaper is inviting submissions from the students for its coming edition on what in their university impresses them most. You are now to write an essay for submission. You will have 30 minutes to write the essay. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2023年12月 第3套', 17, 'PUBLISHED'),
  ('cet4-2024-06-1', 'ESSAY', 'CET4', '图书馆该对公众开放吗', '就大学图书馆是否应向公众开放表达你的观点，不少于 120 词。', 'Suppose your university is seeking students’ opinions on whether university libraries should be open to the public. You are now to write an essay to express your view. You will have 30 minutes for the task. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2024年6月 第1套', 18, 'PUBLISHED'),
  ('cet4-2024-06-2', 'ESSAY', 'CET4', '体育设施该对公众开放吗', '就大学体育设施是否应向公众开放表达你的观点，不少于 120 词。', 'Suppose your university is seeking students’ opinions on whether university sports facilities should be open to the public. You are now to write an essay to express your view. You will have 30 minutes for the task. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2024年6月 第2套', 19, 'PUBLISHED'),
  ('cet4-2024-06-3', 'ESSAY', 'CET4', '食堂该对公众开放吗', '就大学食堂是否应向公众开放表达你的观点，不少于 120 词。', 'Suppose your university is seeking students’ opinions on whether university canteens should be open to the public. You are now to write an essay to express your view. You will have 30 minutes for the task. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2024年6月 第3套', 20, 'PUBLISHED'),
  ('cet4-2024-12-1', 'ESSAY', 'CET4', '快递业发展与生活影响', '论述我国快递业的发展及其对人们生活的影响，不少于 120 词。', 'Suppose the business school of your university is conducting a survey to collect students'' opinions on the express delivery service industry in China. You are to write a response about its recent development and its impact on people''s lives. You will have 30 minutes to write the essay. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2024年12月 第1套', 21, 'PUBLISHED'),
  ('cet4-2024-12-2', 'ESSAY', 'CET4', '投稿：丰富传统文化认知', '为校报投稿，谈如何丰富学生对中华传统文化的了解，不少于 120 词。', 'Suppose the university newspaper is inviting submissions from the students for its coming edition on how to enrich students'' knowledge of traditional Chinese culture. You are now to write an essay for submission. You will have 30 minutes to write the essay. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2024年12月 第2套', 22, 'PUBLISHED'),
  ('cet4-2024-12-3', 'ESSAY', 'CET4', '投稿：共建绿色校园', '为校报投稿，谈学生如何为建设绿色校园出力，不少于 120 词。', 'Suppose the university newspaper is inviting submissions from the students for its coming edition on how the students can contribute to a green campus. You are now to write an essay for submission. You will have 30 minutes to write the essay. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2024年12月 第3套', 23, 'PUBLISHED'),
  ('cet4-2025-06-1', 'ESSAY', 'CET4', '大学语文该设为必修吗', '就“大学语文应设为必修课”的必要性表达你的观点，不少于 120 词。', 'Suppose your university is seeking students'' opinions on the necessity of making College Chinese a compulsory course. You are now to write an essay to express your view. You will have 30 minutes for the task. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2025年6月 第1套', 24, 'PUBLISHED'),
  ('cet4-2025-06-2', 'ESSAY', 'CET4', 'AI 辅助学习的合理使用', '就如何合理使用 AI 技术辅助学习表达你的观点，不少于 120 词。', 'Suppose your university is conducting a survey to collect students'' opinions on the appropriate use of AI technology in assisting learning. You are now to write an essay to express your view. You will have 30 minutes for the task. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2025年6月 第2套', 25, 'PUBLISHED'),
  ('cet4-2025-06-3', 'ESSAY', 'CET4', '培养跨文化交际能力', '就学生跨文化交际能力的发展表达你的观点，不少于 120 词。', 'Suppose your university is organizing a forum on the development of students'' cross-cultural communication abilities. You are now to write an essay to express your view. You will have 30 minutes to write the essay. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2025年6月 第3套', 26, 'PUBLISHED'),
  ('cet4-2025-12-1', 'ESSAY', 'CET4', '为学生会工作提建议', '就学生会如何更好地丰富学生生活提出建议，不少于 120 词。', 'Suppose the student union of your university is collecting opinions on improving its work for the coming year. You are now to write a response by suggesting how it can better enrich student life. You will have 30 minutes to write the essay. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2025年12月 第1套', 27, 'PUBLISHED'),
  ('cet4-2025-12-2', 'ESSAY', 'CET4', '学术写作该人人必修吗', '就“所有大学生都应学习学术写作”这一提议表达你的看法，不少于 120 词。', 'Suppose it is proposed that all university students should be required to learn academic writing. You are now to write a response by stating what you think of the proposal. You will have 30 minutes to write the essay. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2025年12月 第2套', 28, 'PUBLISHED'),
  ('cet4-2025-12-3', 'ESSAY', 'CET4', '善用校内学术资源', '就学生如何充分利用校内资源促进学业发展表达你的观点，不少于 120 词。', 'Suppose your university is organizing a forum on how students can make the best use of on-campus resources for academic development. You are now to write an essay to express your view. You will have 30 minutes to write the essay. You should write at least 120 words but no more than 180 words.', 120, 180, 1800, 'CET4 2025年12月 第3套', 29, 'PUBLISHED'),
  ('cet4-2026-06-1', 'ESSAY', 'CET4', '人人参与科研项目可行吗', '就“大学生须参与至少一项科研项目”的提议，从必要性与可行性两方面表达看法，不少于 120 词。', 'Suppose it is proposed that university students should be required to participate in at least one research project. You are now to write a response by stating what you think of the proposal in terms of its necessity and practicality. You will have 30 minutes to write the response. You should write at least 120 words but not more than 180 words.', 120, 180, 1800, 'CET4 2026年6月 第1套', 30, 'PUBLISHED'),
  ('cet4-2026-06-2', 'ESSAY', 'CET4', '投稿：机器人在校园的未来', '为校报投稿，谈机器人技术在校园的未来应用，不少于 120 词。', 'Suppose your university newspaper is inviting submissions from the students for its coming edition on future applications of robots on campus. You are now to write an essay for submission. You will have 30 minutes to write the essay. You should write at least 120 words but not more than 180 words.', 120, 180, 1800, 'CET4 2026年6月 第2套', 31, 'PUBLISHED'),
  ('cet4-2026-06-3', 'ESSAY', 'CET4', '让校园生活更便利', '就如何让学生的校园生活更便利提出建议，不少于 120 词。', 'Suppose you are invited to put forward a proposal to the university on how to make students'' campus life easier. You are now to write an essay to make your proposal. You will have 30 minutes to write the essay. You should write at least 120 words but not more than 180 words.', 120, 180, 1800, 'CET4 2026年6月 第3套', 32, 'PUBLISHED'),
  ('cet6-2021-06-1', 'CHART_ESSAY', 'CET6', '图表：中国城镇化成就', '描述所给图表，并就中国在城镇化方面取得的成就发表评论，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay based on the graph below. You should start your essay with a brief description of the graph and comment on China''s achievements in urbanization. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2021年6月 第1套', 33, 'OFFLINE'),
  ('cet6-2021-06-2', 'CHART_ESSAY', 'CET6', '图表：中国高等教育成就', '描述所给图表，并就中国在高等教育方面取得的成就发表评论，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay based on the chart below. You should start your essay with a brief description of the chart and comment on China''s achievements in higher education . You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2021年6月 第2套', 34, 'OFFLINE'),
  ('cet6-2021-06-3', 'CHART_ESSAY', 'CET6', '图表：中国脱贫成就', '描述所给图表，并就中国在脱贫攻坚方面取得的成就发表评论，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay based on the chart below. You should start your essay with a brief description of the chart and comment on China''s achievements in poverty alleviation. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2021年6月 第3套', 35, 'OFFLINE'),
  ('cet6-2022-06-1', 'QUOTE_ESSAY', 'CET6', '环保生活方式渐成潮流', '以给定句子开头，论述越来越多人选择环保的生活方式，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “Nowadays more and more people choose to live an environmentally friendly lifestyle.” You can make comments, cite examples, or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2022年6月 第1套', 36, 'PUBLISHED'),
  ('cet6-2022-09-1', 'QUOTE_ESSAY', 'CET6', '数字技能的重要性', '以给定句子开头，论述学生日益重视培养数字技能，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “Nowadays more and more students are becoming increasingly aware of the importance of developing digital skills.” You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2022年9月 第1套', 37, 'PUBLISHED'),
  ('cet6-2022-09-2', 'QUOTE_ESSAY', 'CET6', '重拾真实社交的乐趣', '以给定句子开头，论述人们重新认识到现实社交的乐趣，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “Today more and more people begin to realize the pleasures and joys of real-world social interaction.” You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2022年9月 第2套', 38, 'PUBLISHED'),
  ('cet6-2022-09-3', 'QUOTE_ESSAY', 'CET6', '互信与开放是合作之基', '以给定句子开头，论述互信与开放是促进合作的关键，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “It is now widely accepted that mutual trust and openness is the key to promoting cooperation.” You can make comments, cite examples, or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2022年9月 第3套', 39, 'PUBLISHED'),
  ('cet6-2022-12-1', 'QUOTE_ESSAY', 'CET6', '信息技术让学习更多元', '以给定句子开头，论述信息技术给大学生学习方式带来的变化，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence“With the application of information technology in education, college students can now learn in more diverse and efficient ways.” You can make statements, give reasons, or cite examples to develop your essay. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2022年12月 第1套', 40, 'PUBLISHED'),
  ('cet6-2022-12-2', 'QUOTE_ESSAY', 'CET6', '信息爆炸时代的批判性思维', '以给定句子开头，论述培养批判性思维与理性选择能力的重要性，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “In an era of information explosion, it is vitally important to develop the ability to think critically and make rational choices.” You can make statements, give reasons, or cite examples to develop your essay. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2022年12月 第2套', 41, 'PUBLISHED'),
  ('cet6-2022-12-3', 'QUOTE_ESSAY', 'CET6', '培养大学生团队精神', '以给定句子开头，论述培养大学生团队精神日益受到重视，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence“Today increasing importance is being attached to cultivating college students'' team spirit.” You can make statements, give reasons, or cite examples to develop your essay. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2022年12月 第3套', 42, 'PUBLISHED'),
  ('cet6-2023-03-1', 'QUOTE_ESSAY', 'CET6', '容貌焦虑的隐忧', '以给定句子开头，论述“容貌焦虑”或过度在意外表所带来的危害，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “People are now increasingly aware of the danger of ‘appearance anxiety’ or being obsessed with one’s looks.” You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2023年3月 第1套', 43, 'PUBLISHED'),
  ('cet6-2023-03-2', 'QUOTE_ESSAY', 'CET6', '选择越多越难决策', '以给定句子开头，论述选择过多时的决策困境，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “People are now increasingly aware of the challenges in making a decision when faced with too many choices.” You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2023年3月 第2套', 44, 'PUBLISHED'),
  ('cet6-2023-03-3', 'QUOTE_ESSAY', 'CET6', '老年人面对的数字鸿沟', '以给定句子开头，论述老年人在数字世界面临的挑战，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “People are now increasingly aware of the ‘digital gap’ or challenges the elderly face in a digital world.” You can make comments, give explanations, or cite examples to develop your essay. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2023年3月 第3套', 45, 'PUBLISHED'),
  ('cet6-2023-06-1', 'QUOTE_ESSAY', 'CET6', '心理健康值得同等重视', '以给定句子开头，论述心理健康应与身体健康同等受重视，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence " Today there is a growing awareness that mental well-being needs to be given as much attention as physical health." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words', 150, 200, 1800, 'CET6 2023年6月 第1套', 46, 'PUBLISHED'),
  ('cet6-2023-06-2', 'QUOTE_ESSAY', 'CET6', '分歧中如何达成共识', '以给定句子开头，论述面对分歧应通过友好讨论与理性论证达成一致，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “When faced with differing opinions, we should try to reach agreement through friendly discussion and reasonable argument.” You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words(not including the sentence given).', 150, 200, 1800, 'CET6 2023年6月 第2套', 47, 'PUBLISHED'),
  ('cet6-2023-06-3', 'QUOTE_ESSAY', 'CET6', '教育的核心是学会学习', '以给定句子开头，论述教育的重要目标是帮助学生学会如何学习，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence " It is widely accepted that an important goal of education is to help students learn how to learn." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2023年6月 第3套', 48, 'PUBLISHED'),
  ('cet6-2023-12-1', 'QUOTE_ESSAY', 'CET6', '打好基础方能精通', '以给定句子开头，论述掌握基础知识对学好一门学科的重要性，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence " As is known to all, gaining a sound knowledge of the basics is of vital importance for students to master an academic subject.” You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words (not including the sentence given).', 150, 200, 1800, 'CET6 2023年12月 第1套', 49, 'PUBLISHED'),
  ('cet6-2023-12-2', 'QUOTE_ESSAY', 'CET6', '给孩子探索的自由', '以给定句子开头，论述给孩子更多自主探索的自由有助于培养独立性与自信，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “Nowadays parents are increasingly aware that allowing kids more freedom to explore and learn on their own helps foster their independence and boost their confidence.” You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words(not including the sentence given).', 150, 200, 1800, 'CET6 2023年12月 第2套', 50, 'PUBLISHED'),
  ('cet6-2023-12-3', 'QUOTE_ESSAY', 'CET6', '老年人仍可贡献社会', '以给定句子开头，论述老年人凭宝贵的技能与经验仍能继续贡献社会，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “With their valuable skills and experience, elderly people can continue to make significant contributions to society." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words.', 150, 200, 1800, 'CET6 2023年12月 第3套', 51, 'PUBLISHED'),
  ('cet6-2024-06-1', 'QUOTE_ESSAY', 'CET6', '培养自主学习能力', '以给定句子开头（须抄写该句），论述培养自主学习能力对个人发展日益重要，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “Nowadays, cultivating independent learning ability is becoming increasingly crucial for personal development.” You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. (You should copy the sentence given in quotes at the beginning of your essay.)', 150, 200, 1800, 'CET6 2024年6月 第1套', 52, 'PUBLISHED'),
  ('cet6-2024-06-2', 'QUOTE_ESSAY', 'CET6', '社会实践与学业同等重要', '以给定句子开头（须抄写该句），论述大学生认识到社会实践与学业同等重要，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “Nowadays more and more college students have come to realize social practice and academic learning are equally important.” You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. (You should copy the sentence given in quotes at the beginning of your essay.)', 150, 200, 1800, 'CET6 2024年6月 第2套', 53, 'PUBLISHED'),
  ('cet6-2024-06-3', 'QUOTE_ESSAY', 'CET6', '数字素养至关重要', '以给定句子开头（须抄写该句），论述当今世界数字素养与技能的重要性，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “There is a growing awareness of the importance of digital literacy and skills in today’s world.” You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. (You should copy the sentence given in quotes at the beginning of your essay. )', 150, 200, 1800, 'CET6 2024年6月 第3套', 54, 'PUBLISHED'),
  ('cet6-2024-12-1', 'QUOTE_ESSAY', 'CET6', '设定目标并持之以恒', '以给定句子开头（须抄写该句），论述设定现实目标并坚持努力才能提高成功概率，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “To increase the likelihood of success, one should set realistic goals and work persistently towards them." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.', 150, 200, 1800, 'CET6 2024年12月 第1套', 55, 'PUBLISHED'),
  ('cet6-2024-12-2', 'QUOTE_ESSAY', 'CET6', '自律助你成长', '以给定句子开头（须抄写该句），论述自律对个人成长的重要性，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence " Nowadays, more and more students have realized the importance of self-discipline in their personal growth." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.', 150, 200, 1800, 'CET6 2024年12月 第2套', 56, 'PUBLISHED'),
  ('cet6-2024-12-3', 'QUOTE_ESSAY', 'CET6', '大学是探索可能的舞台', '以给定句子开头（须抄写该句），论述大学为学生探索多种可能、找到自身方向提供了机会，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence “College provides a great opportunity for students to explore various possibilities and find the right path for themselves.” You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.', 150, 200, 1800, 'CET6 2024年12月 第3套', 57, 'PUBLISHED'),
  ('cet6-2025-06-1', 'QUOTE_ESSAY', 'CET6', '为未来职业做好准备', '以给定句子开头（须抄写该句），论述就业要求提高背景下大学生应做好职业准备，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence " As requirements for job applications are getting increasingly higher, college students ought to be better prepared for their future career." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.', 150, 200, 1800, 'CET6 2025年6月 第1套', 58, 'PUBLISHED'),
  ('cet6-2025-06-2', 'QUOTE_ESSAY', 'CET6', '负责任地使用社交媒体', '以给定句子开头（须抄写该句），论述社交媒体普及背景下应正确、负责任地使用它，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence " As social media is used more and more extensively, there is a growing awareness of the importance of using it properly and responsibly." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.', 150, 200, 1800, 'CET6 2025年6月 第2套', 59, 'PUBLISHED'),
  ('cet6-2025-06-3', 'QUOTE_ESSAY', 'CET6', 'AI 会削弱人类创造力吗', '以给定句子开头（须抄写该句），论述 AI 技术广泛应用可能损害人类创造力的担忧，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence " With the increasing application of AI technology, there is a growing concern that it may negatively impact human creativity." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.', 150, 200, 1800, 'CET6 2025年6月 第3套', 60, 'PUBLISHED'),
  ('cet6-2025-12-1', 'QUOTE_ESSAY', 'CET6', '中国梦与青年自我价值', '以给定句子开头（须抄写该句），论述青年在追逐中国梦的过程中获得更多实现自我价值的机会，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence " While striving for the Chinese Dream, young people enjoy more opportunities to realize their self-worth." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.', 150, 200, 1800, 'CET6 2025年12月 第1套', 61, 'PUBLISHED'),
  ('cet6-2025-12-2', 'QUOTE_ESSAY', 'CET6', '教师对学生的影响', '以给定句子开头（须抄写该句），论述教师对学生学业追求与个人发展的深远影响，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence " It is believed that teachers can exert a profound influence on their students'' academic pursuit and personal development." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.', 150, 200, 1800, 'CET6 2025年12月 第2套', 62, 'PUBLISHED'),
  ('cet6-2025-12-3', 'QUOTE_ESSAY', 'CET6', '在竞争世界中做好准备', '以给定句子开头（须抄写该句），论述竞争日益激烈的世界里大学生应做好准备迎接挑战，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence "Living in an increasingly competitive world, college students should better prepare themselves to confront various challenges." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.', 150, 200, 1800, 'CET6 2025年12月 第3套', 63, 'PUBLISHED'),
  ('cet6-2026-06-1', 'QUOTE_ESSAY', 'CET6', '城镇化中重拾对自然的热爱', '以给定句子开头（须抄写该句），论述城镇化趋势下城市居民应培养对自然更深的热爱，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence " With the trend of Urbanization, it is vitally important for city residents to develop a stronger love for Nature." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.', 150, 200, 1800, 'CET6 2026年6月 第1套', 64, 'PUBLISHED'),
  ('cet6-2026-06-2', 'QUOTE_ESSAY', 'CET6', '培养年轻人的责任感', '以给定句子开头（须抄写该句），论述社会发展中增强年轻人责任感的重要性，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence "In an era of rapid social development, it is vitally important to enhance young people''s sense of responsibility." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.', 150, 200, 1800, 'CET6 2026年6月 第2套', 65, 'PUBLISHED'),
  ('cet6-2026-06-3', 'QUOTE_ESSAY', 'CET6', '传统文化涵养文化自信', '以给定句子开头（须抄写该句），论述深入了解中华传统文化有助于培养文化自信，不少于 150 词。', 'For this part, you are allowed 30 minutes to write an essay that begins with the sentence "Faced with growing globalization, students realize that a deep understanding of traditional Chinese culture helps cultivate cultural confidence." You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.', 150, 200, 1800, 'CET6 2026年6月 第3套', 66, 'PUBLISHED');
